package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)
var WsGross decimal.Decimal = decimal.NewFromInt(0)
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var empFile *os.File
var empScanner *bufio.Scanner
var empRec EmpRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func parseEmpRec(line string) EmpRec {
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	}
	if len(line) > 17 {
		line = line[:17]
	}
	erId := line[0:5]
	erDept := line[5:8]
	hoursStr := line[8:12]
	rateStr := line[12:17]

	// PIC 9(3)V9 : 4 digits implied 1 decimal
	hoursVal := parseImpliedDecimal(hoursStr, 1)
	rateVal := parseImpliedDecimal(rateStr, 2)

	return EmpRec{
		ErId:    erId,
		ErDept:  erDept,
		ErHours: hoursVal,
		ErRate:  rateVal,
	}
}

func parseImpliedDecimal(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// digits only
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback strip non digits
		filtered := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered == "" {
			return decimal.NewFromInt(0)
		}
		d, _ = decimal.NewFromString(filtered)
	}
	return decimal.New(d.IntPart(), -scale)
}

// generic numeric-edited formatting
func formatEdited(val decimal.Decimal, pic string) string {
	// count integer and decimal placeholders
	dotPos := strings.Index(pic, ".")
	var intPic, decPic string
	if dotPos >= 0 {
		intPic = pic[:dotPos]
		decPic = pic[dotPos+1:]
	} else {
		intPic = pic
		decPic = ""
	}
	intPlaces := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intPlaces++
		}
	}
	decPlaces := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			decPlaces++
		}
	}
	// truncate toward zero to decPlaces
	truncVal := val.Truncate(int32(decPlaces))
	if truncVal.IsNegative() {
		truncVal = truncVal.Abs()
	}
	// decimal digits
	decDigits := ""
	if decPlaces > 0 {
		// get fractional part with exact decPlaces
		// Use truncVal string with fixed scale
		s := truncVal.StringFixed(int32(decPlaces))
		parts := strings.SplitN(s, ".", 2)
		if len(parts) == 2 {
			decDigits = parts[1]
		} else {
			decDigits = strings.Repeat("0", decPlaces)
		}
		if len(decDigits) < decPlaces {
			decDigits = decDigits + strings.Repeat("0", decPlaces-len(decDigits))
		} else if len(decDigits) > decPlaces {
			decDigits = decDigits[:decPlaces]
		}
	}
	// integer part
	intPart := truncVal.Truncate(0).Abs()
	intStr := intPart.StringFixed(0)
	// StringFixed may give "0" for zero
	if intStr == "" {
		intStr = "0"
	}
	// drop high-order digits if overflow
	if len(intStr) > intPlaces {
		intStr = intStr[len(intStr)-intPlaces:]
	}
	// pad left zeros to intPlaces
	if len(intStr) < intPlaces {
		intStr = strings.Repeat("0", intPlaces-len(intStr)) + intStr
	}
	intDigits := intStr

	// first non-zero index
	firstNZ := -1
	for i, ch := range intDigits {
		if ch != '0' {
			firstNZ = i
			break
		}
	}
	if firstNZ == -1 {
		firstNZ = intPlaces - 1 // keep last digit
	}

	// Build output
	out := make([]rune, len(pic))
	intPlaceholderIdx := 0 // number of int placeholders already placed
	decPlaceholderIdx := 0
	// Need to know placeholders before each position for comma suppression
	// Precompute total int placeholders and positions
	intPlaceCountBefore := make([]int, len(pic))
	cnt := 0
	for i, ch := range pic {
		intPlaceCountBefore[i] = cnt
		if dotPos >= 0 && i < dotPos {
			if ch == 'Z' || ch == '9' {
				cnt++
			}
		} else if dotPos == -1 {
			if ch == 'Z' || ch == '9' {
				cnt++
			}
		}
	}
	// also need to know if we are after dot
	for i, ch := range pic {
		switch ch {
		case 'Z', '9':
			if dotPos >= 0 && i > dotPos {
				// decimal placeholder
				if decPlaceholderIdx < len(decDigits) {
					out[i] = rune(decDigits[decPlaceholderIdx])
				} else {
					out[i] = '0'
				}
				decPlaceholderIdx++
			} else {
				// integer placeholder
				digit := rune(intDigits[intPlaceholderIdx])
				picCh := ch
				if intPlaceholderIdx < firstNZ && picCh == 'Z' {
					out[i] = ' '
				} else {
					out[i] = digit
				}
				intPlaceholderIdx++
			}
		case ',':
			// suppressed if first non-zero is beyond placeholders before comma
			placeholdersBefore := intPlaceCountBefore[i]
			if firstNZ >= placeholdersBefore && placeholdersBefore < intPlaces {
				// check if all before are suppressed: firstNZ >= placeholdersBefore means comma in suppressed zone
				// For case where value is non-zero early, firstNZ small, not suppressed
				// Determine suppression: if firstNZ >= placeholdersBeforeCount? Actually for comma between, need to see if firstNZ >= placeholdersBefore? Use that.
				// But also if firstNZ == intPlaces-1 and value zero, commas are suppressed
				// Use condition: placeholdersBefore <= firstNZ and firstNZ != -1
				// If firstNZ ==0, placeholdersBefore 0 => 0<=0 true would incorrectly suppress leading comma.
				// Need stricter: comma suppressed only if the next non-zero is after comma.
				// So suppressed when firstNZ >= placeholdersBefore and the digit at firstNZ is after comma? That's not.
				// Simpler: comma suppressed if every placeholder before it is suppressed (i.e., placeholdersBefore <= firstNZ and the placeholder at firstNZ is after comma is not enough)
				// For firstNZ=0, placeholdersBefore for first comma maybe 1, then 0>=1 false => not suppressed correct.
				// For firstNZ=1, placeholdersBefore=1 => 1>=1 true => suppressed correct.
				if firstNZ >= placeholdersBefore {
					// But need to ensure not all digits zero? For zero case, all commas suppressed as well, which is fine.
					// For firstNZ=0, a comma with placeholdersBefore=0 would be 0>=0 true but should not be suppressed because that comma is at very start before any digit.
					// However pictures start with Z not comma, so placeholdersBefore=0 comma doesn't exist.
					out[i] = ' '
				} else {
					out[i] = ','
				}
			} else {
				out[i] = ','
			}
			// Adjust: if firstNZ ==0, the first comma has placeholdersBefore=1, so not suppressed.
			// So this works.
			if firstNZ < placeholdersBefore {
				out[i] = ','
			}
		case '.':
			out[i] = '.'
		default:
			out[i] = ch
		}
	}
	// Second pass fix for commas: if firstNZ ==0 the above would have set first comma incorrectly?
	// Re-evaluate commas more accurately: comma is space iff all integer placeholders before it are spaces
	// We can compute placeholders before comma and whether any of them is non-space in output.
	// Let's fix commas by checking output.
	// Actually simpler: recompute commas: if every placeholder before comma is suppressed (space), then comma = space else ','
	for i, ch := range pic {
		if ch == ',' {
			placeholdersBefore := intPlaceCountBefore[i]
			suppressed := true
			if placeholdersBefore > firstNZ {
				suppressed = false
			} else {
				// if placeholdersBefore ==0 -> there is no placeholder before, cannot determine; treat as suppressed if firstNZ>=0? But such pic doesn't exist.
				// For our method, suppressed true when firstNZ >= placeholdersBefore
				// But we need to ensure at least placeholdersBefore >0 and all before are suppressed
				// All before are suppressed iff placeholdersBefore <= firstNZ
				suppressed = placeholdersBefore <= firstNZ
				// However when firstNZ==0, placeholdersBefore==1 => 1<=0 false => not suppressed correct
				// When firstNZ==1, placeholdersBefore==1 => 1<=1 true => suppressed correct
			}
			if suppressed {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
	}
	return string(out)
}

func formatUneditedInt(v int64, width int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func MAINPARA() {
	empFile, _ = os.Open("input.dat")
	if empFile != nil {
		empScanner = bufio.NewScanner(empFile)
	}
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if !isFirstRecord() {
		DEPTBREAKPARA()
	}
	if empFile != nil {
		empFile.Close()
	}
	GRANDPARA()
}

func READPARA() {
	if empScanner != nil && empScanner.Scan() {
		line := empScanner.Text()
		empRec = parseEmpRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	if isFirstRecord() {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			DEPTBREAKPARA()
			WsPrevDept = empRec.ErDept
		}
	}
	PAYPARA()
	READPARA()
}

func PAYPARA() {
	forty := decimal.NewFromInt(40)
	if empRec.ErHours.GreaterThan(forty) {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = empRec.ErHours.Sub(decimal.NewFromInt(40))
	} else {
		WsRegHours = empRec.ErHours
		WsOtHours = decimal.NewFromInt(0)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	onePointFive := decimal.NewFromFloat(1.5)
	val := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(onePointFive))
	// ROUNDED to scale 2
	WsGross = val.Round(2)
	// truncate/store to PIC 9(7)V99 - for this range fits
	WsGross = WsGross.Truncate(2)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptCount++
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandCount++

	WsHoursEd = formatEdited(empRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(empRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", empRec.ErId, empRec.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPTBREAKPARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GRANDPARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func main() {
	MAINPARA()
}
